// Prints the JSON Schema (draft 2020-12) of a theme contract root type.
//
//   dart run bin/print_json_schema.dart                    # ThemeSettings, pretty-printed
//   dart run bin/print_json_schema.dart AppConfig
//   dart run bin/print_json_schema.dart --list             # available roots
//   dart run bin/print_json_schema.dart --out schema.json  # write to a file
//
// The schemas themselves are generated by json_serializable's `create_json_schema`
// option (see build.yaml) and exposed as `<Type>.jsonSchema`.

import 'dart:convert';
import 'dart:io';

import 'package:webtrit_appearance_theme/webtrit_appearance_theme.dart';

const _roots = <String, Map<String, Object?>>{
  'ThemeSettings': ThemeSettings.jsonSchema,
  'AppConfig': AppConfig.jsonSchema,
  'EmbeddedResource': EmbeddedResource.jsonSchema,
};

void main(List<String> args) {
  if (args.contains('--help') || args.contains('-h')) {
    stdout.writeln(_usage);
    return;
  }
  if (args.contains('--list')) {
    _roots.keys.forEach(stdout.writeln);
    return;
  }

  final outIndex = args.indexOf('--out');
  if (outIndex == args.length - 1) {
    stderr.writeln('--out requires a file path.\n\n$_usage');
    exitCode = 64;
    return;
  }
  final outPath = outIndex == -1 ? null : args[outIndex + 1];

  final positional = <String>[];
  for (var i = 0; i < args.length; i++) {
    if (args[i].startsWith('-')) {
      if (args[i] == '--out') i++;
      continue;
    }
    positional.add(args[i]);
  }

  final rootName = positional.isEmpty ? _roots.keys.first : positional.first;
  final schema = _roots[rootName];
  if (schema == null) {
    stderr.writeln('Unknown schema root: $rootName. Known roots: ${_roots.keys.join(', ')}.');
    exitCode = 64;
    return;
  }

  final encoder = args.contains('--compact') ? const JsonEncoder() : const JsonEncoder.withIndent('  ');
  final encoded = encoder.convert(schema);

  if (outPath == null) {
    stdout.writeln(encoded);
  } else {
    File(outPath).writeAsStringSync('$encoded\n');
    stdout.writeln('Wrote $rootName schema to $outPath');
  }
}

const _usage = '''
Prints the JSON Schema of a webtrit_appearance_theme root type.

Usage: dart run bin/print_json_schema.dart [root] [options]

Options:
  --list       list the available schema roots
  --compact    do not indent the output
  --out FILE   write the schema to FILE instead of stdout
  -h, --help   show this help
''';
